<?php require '_init.php';$pageTitle='Store overview';$stats=['Total orders'=>query('SELECT COUNT(*) FROM orders')->fetchColumn(),'Delivered revenue'=>money(query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Delivered'")->fetchColumn()),'Customers'=>query('SELECT COUNT(*) FROM users')->fetchColumn(),'Unread messages'=>query('SELECT COUNT(*) FROM messages WHERE is_read=0')->fetchColumn()];require '../includes/header.php';?><section class="container section"><span class="eyebrow">FALCON PERFUMES / ADMIN</span><h1>Store overview</h1><div class="stats"><?php foreach($stats as $label=>$value):?><div class="panel"><span class="muted"><?=$label?></span><strong><?=$value?></strong></div><?php endforeach;?></div><div class="section-head"><h2>Low stock & sold out</h2><a class="button" href="<?=e(url('admin/product-edit.php'))?>">Add perfume</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Availability</th><th>Action</th></tr></thead><tbody><?php foreach(query('SELECT * FROM products WHERE is_active=1 AND (stock<=5 OR is_sold_out=1) ORDER BY stock')->fetchAll() as $p):?><tr><td><?=e($p['name'])?></td><td><?=$p['stock']?></td><td><?=available($p)?'Low stock':'Sold Out'?></td><td><a href="<?=e(url('admin/product-edit.php?id='.$p['id']))?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div><h2>Recent orders</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach(query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll() as $o):?><tr><td><a href="<?=e(url('admin/orders.php?id='.$o['id']))?>">#<?=$o['id']?></a></td><td><?=e($o['customer_name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
